'use client';

import React, { useState } from 'react';
import { Calculator, Home, ArrowRight } from 'lucide-react';

const EmiCalculator = () => {
    // State matching the "Property Value Calculator" fields from the image
    // The user requested "emi calculator" but provided a reference image for "Property Value Calculator"
    // and requested "same as it is". Thus, implementing the visual interface of the image.
    const [lookingTo, setLookingTo] = useState('Sell');
    const [city, setCity] = useState('Mumbai');
    const [project, setProject] = useState('');
    const [locality, setLocality] = useState('Andheri West, Mumbai');
    const [propertyType, setPropertyType] = useState('Apartment');
    const [bedrooms, setBedrooms] = useState('1');
    const [area, setArea] = useState('');

    const propertyTypes = ['Apartment', 'Independent Floor', 'Independent House', 'Villa'];
    const bedroomOptions = ['1', '2', '3', '4', '5+'];

    return (
        <div className="min-h-screen bg-[#B88746] relative overflow-hidden flex items-center justify-center p-4 pt-24">
            {/* Background Pattern similar to image */}
            <div className="absolute top-0 right-0 w-full h-full opacity-10 pointer-events-none overflow-hidden">
                <div className="absolute top-20 -right-20 transform rotate-12">
                    <svg className="w-96 h-96 text-white" viewBox="0 0 24 24" fill="currentColor"><path d="M10 20v-6h4v6h5v-8h3L12 3 2 12h3v8z" /></svg>
                </div>
                <div className="absolute bottom-10 left-10 transform -rotate-12">
                    <svg className="w-64 h-64 text-white" viewBox="0 0 24 24" fill="currentColor"><path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-7 0a2 2 0 1 0 0 4 2 2 0 0 0 0-4z" /></svg>
                </div>
            </div>

            <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-4xl relative z-10 p-10 md:p-16 animate-fadeIn">
                <div className="mb-10">
                    <h1 className="text-4xl font-bold text-gray-900">Property Value Calculator</h1>
                    <p className="text-gray-500 mt-3 text-base">Let's calculate sale or rent value in seconds</p>
                </div>

                <div className="space-y-10">
                    {/* Looking to */}
                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-3">Looking to <span className="text-red-500">*</span></label>
                        <div className="flex gap-4">
                            {['Sell', 'Rent'].map((option) => (
                                <button
                                    key={option}
                                    onClick={() => setLookingTo(option)}
                                    className={`px-8 py-2.5 rounded-xl text-sm font-semibold transition-all border
                                        ${lookingTo === option
                                            ? 'bg-purple-100 text-purple-700 border-purple-200 shadow-sm'
                                            : 'bg-white text-gray-500 border-gray-200 hover:border-gray-300'
                                        }`}
                                >
                                    {option}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* City */}
                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-2">City <span className="text-red-500">*</span></label>
                        <input
                            type="text"
                            value={city}
                            onChange={(e) => setCity(e.target.value)}
                            className="w-full border-b-2 border-gray-100 py-3 text-lg focus:outline-none focus:border-purple-500 text-gray-900 placeholder-gray-400 font-medium transition-colors"
                            placeholder="Enter City"
                        />
                    </div>

                    {/* Project & Locality (Stacked as per image, assuming image continues downwards) */}
                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-2">Project</label>
                        <input
                            type="text"
                            value={project}
                            onChange={(e) => setProject(e.target.value)}
                            className="w-full border-b-2 border-gray-100 py-3 text-lg focus:outline-none focus:border-purple-500 text-gray-900 placeholder-gray-400 font-medium transition-colors"
                            placeholder="Enter Project Name"
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-2">Locality <span className="text-red-500">*</span></label>
                        <input
                            type="text"
                            value={locality}
                            onChange={(e) => setLocality(e.target.value)}
                            className="w-full border-b-2 border-gray-100 py-3 text-lg focus:outline-none focus:border-purple-500 text-gray-900 placeholder-gray-400 font-medium transition-colors"
                            placeholder="Enter Locality"
                        />
                    </div>

                    {/* Property Type */}
                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-3">Property Type <span className="text-red-500">*</span></label>
                        <div className="flex flex-wrap gap-3">
                            {propertyTypes.map((type) => (
                                <button
                                    key={type}
                                    onClick={() => setPropertyType(type)}
                                    className={`px-6 py-2.5 rounded-xl text-xs font-semibold transition-all border
                                        ${propertyType === type
                                            ? 'bg-purple-100 text-purple-700 border-purple-200 shadow-sm'
                                            : 'bg-white text-gray-500 border-gray-200 hover:border-gray-300'
                                        }`}
                                >
                                    {type}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Bedrooms */}
                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-3">Bedrooms <span className="text-red-500">*</span></label>
                        <div className="flex flex-wrap gap-3">
                            {bedroomOptions.map((opt) => (
                                <button
                                    key={opt}
                                    onClick={() => setBedrooms(opt)}
                                    className={`w-12 h-12 flex items-center justify-center rounded-xl text-sm font-semibold transition-all border
                                        ${bedrooms === opt
                                            ? 'bg-purple-100 text-purple-700 border-purple-200 shadow-sm'
                                            : 'bg-white text-gray-500 border-gray-200 hover:border-gray-300'
                                        }`}
                                >
                                    {opt}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Area */}
                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-2">Area (sq.ft) <span className="text-red-500">*</span></label>
                        <input
                            type="number"
                            value={area}
                            onChange={(e) => setArea(e.target.value)}
                            className="w-full border-b-2 border-gray-100 py-3 text-lg focus:outline-none focus:border-purple-500 text-gray-900 placeholder-gray-400 font-medium transition-colors"
                            placeholder="0"
                        />
                    </div>

                    <div className="pt-6">
                        <button className="w-full bg-[#172747] text-white py-4 rounded-2xl font-bold text-lg hover:bg-[#0f1b33] transition-colors flex items-center justify-center gap-2 shadow-xl hover:shadow-2xl transform hover:-translate-y-1">
                            Calculate Value
                            <ArrowRight className="w-5 h-5" />
                        </button>
                    </div>

                </div>
            </div>

            <style jsx global>{`
                @keyframes fadeIn {
                    from { opacity: 0; transform: translateY(30px); }
                    to { opacity: 1; transform: translateY(0); }
                }
                .animate-fadeIn {
                    animation: fadeIn 0.6s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
                }
            `}</style>
        </div>
    );
};

export default EmiCalculator;
